function paymentDetail(){const p=data.pagamentos.find(x=>x.id===ui.selectedPayment),a=data.alunos.find(x=>x.id===p?.alunoId);if(!p||!a){ui.selectedPayment=null;return payments()}return header('PAGAMENTO',p.ref,'<button class="close" data-close-payment>×</button>')+`<section class="panel payment-detail"><button class="payment-person payment-student-link" data-student="${a.id}">${avatar(a)}<span><b>${esc(a.nome)}</b><small>${esc(a.plano)}${a.plano==='Por aula'?` · ${esc(money(a.valor))} por aula`:''}</small></span><i>›</i></button><div class="detail-line"><span>Status</span><b class="${p.pago?'ok':'pending-text'}">${p.pago?'Recebido':'Pendente'}</b></div><div class="detail-line"><span>Valor</span>${secretMoney(p.valor)}</div><div class="detail-line"><span>Confirmado em</span><b>${p.pagoEm?esc(p.pagoEm.split('-').reverse().join('/')):'Ainda não confirmado'}</b></div><label class="detail-note">Comentário<textarea data-payment-note placeholder="Comprovante, forma de pagamento ou observação...">${esc(p.notes||'')}</textarea></label>${p.pago?`<button class="cancel-payment" data-cancel-payment="${p.id}">Cancelar confirmação</button>`:`<button class="save" data-pay="${p.id}">Confirmar pagamento</button>`}</section>`}
function ensurePaymentsForMonth(offset=0){
  const date=monthDate(offset),key=monthKey(date),monthName=date.toLocaleDateString('pt-BR',{month:'long'}),year=date.getFullYear(),first=`${key}-01`,last=localISO(new Date(date.getFullYear(),date.getMonth()+1,0));
  data.alunos.filter(a=>a.ativo!==false&&(!a.desde||a.desde<=last)).forEach(a=>{
    if(a.plano==='Mensal'){
      const dueDate=a.desde&&a.desde>first?a.desde:first,autoKey=`${a.id}-monthly-${key}`,existing=data.pagamentos.find(p=>p.autoKey===autoKey||(!p.autoKey&&p.alunoId===a.id&&norm(p.ref).includes(norm(monthName))&&String(p.ref).includes(String(year))));
      if(existing){existing.autoKey=autoKey;existing.dueDate=existing.dueDate||dueDate}else data.pagamentos.push({id:Date.now()+Math.random(),alunoId:a.id,ref:`${monthName[0].toUpperCase()+monthName.slice(1)}/${year}`,valor:a.valor,pago:false,dueDate,autoKey});
    }else classSlots(a).forEach((slot,slotIndex)=>datesForSlotInMonth(date,slot).filter(day=>(!a.desde||day>=a.desde)&&(!a.encerradoEm||day<=a.encerradoEm)).forEach(day=>{const autoKey=`${a.id}-class-${day}-${slotIndex}`;if(!data.pagamentos.some(p=>p.autoKey===autoKey))data.pagamentos.push({id:Date.now()+Math.random(),alunoId:a.id,ref:`Aula ${day.split('-').reverse().slice(0,2).join('/')}`,valor:a.valor,pago:false,dueDate:day,autoKey})}));
  });save();
}
function ensureWeekRecords(){data.classRecords=data.classRecords||[];const monday=weekStart();data.alunos.filter(a=>a.ativo!==false).forEach(a=>classSlots(a).forEach((slot,index)=>{const date=new Date(monday);date.setDate(monday.getDate()+DAYS.indexOf(slot.dia));const day=localISO(date);if((a.desde&&day<a.desde)||(a.encerradoEm&&day>a.encerradoEm))return;const id=`regular-${a.id}-${day}-${index}`;if(!data.classRecords.some(r=>r.id===id))data.classRecords.push({id,studentId:a.id,date:day,time:slot.hora,duration:slot.duracao||50,status:'pending',day:slot.dia})}));save()}
function ensureMonthClassRecords(offset=0){data.classRecords=data.classRecords||[];const base=monthDate(offset),last=new Date(base.getFullYear(),base.getMonth()+1,0).getDate();data.alunos.forEach(a=>classSlots(a).forEach((slot,index)=>{const wanted=(DAYS.indexOf(slot.dia)+1)%7;for(let d=1;d<=last;d++){const date=new Date(base.getFullYear(),base.getMonth(),d),day=localISO(date);if(date.getDay()!==wanted||(a.desde&&day<a.desde)||(a.encerradoEm&&day>a.encerradoEm))continue;const id=`regular-${a.id}-${day}-${index}`;if(!data.classRecords.some(r=>r.id===id))data.classRecords.push({id,studentId:a.id,date:day,time:slot.hora,duration:slot.duracao||50,status:'pending',day:slot.dia})}}));save()}
function stopStudent(studentId){const a=data.alunos.find(x=>x.id===studentId);if(!a)return;if(a.ativo===false){a.ativo=true;delete a.encerradoEm;ensurePaymentsForMonth(0);save();toast('Aluno reativado');render();return}const end=todayISO(),monthStart=end.slice(0,7)+'-01',monthEnd=localISO(new Date(new Date().getFullYear(),new Date().getMonth()+1,0));a.ativo=false;a.encerradoEm=end;data.classRecords=(data.classRecords||[]).filter(r=>r.studentId!==a.id||r.date<=end);data.pagamentos=data.pagamentos.filter(p=>p.alunoId!==a.id||!p.dueDate||p.dueDate<=end);if(confirm('Excluir também todos os pagamentos restantes deste aluno no mês atual? Isso pode incluir pagamentos já confirmados.'))data.pagamentos=data.pagamentos.filter(p=>p.alunoId!==a.id||!p.dueDate||p.dueDate<monthStart||p.dueDate>monthEnd);save();toast('Aulas encerradas; registros futuros removidos');render()}
