// Portable, photo-free backups (v1.1.5)
const BACKUP_FORMAT='compasso-backup';
const BACKUP_VERSION=1;
const BACKUP_MAX_BYTES=10*1024*1024;
function photoFreeClone(value){return JSON.parse(JSON.stringify(value,(key,item)=>key==='foto'?undefined:item))}
function backupFileStamp(date=new Date(),withTime=false){const day=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;return withTime?`${day}-${String(date.getHours()).padStart(2,'0')}${String(date.getMinutes()).padStart(2,'0')}`:day}
function formatBackupDate(value){if(!value)return 'Nenhum backup exportado';const date=new Date(value);return Number.isNaN(date.getTime())?'Data não disponível':date.toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}
function formatFileSize(bytes){if(bytes<1024)return `${bytes} B`;if(bytes<1024*1024)return `${(bytes/1024).toFixed(1).replace('.',',')} KB`;return `${(bytes/1024/1024).toFixed(1).replace('.',',')} MB`}
function createBackupDocument(exportedAt=new Date().toISOString()){const backupData=photoFreeClone(data);backupData.settings=backupData.settings||{};backupData.settings.lastBackupAt=exportedAt;return {format:BACKUP_FORMAT,backupVersion:BACKUP_VERSION,appVersion:APP_VERSION,exportedAt,data:backupData}}
function triggerJsonDownload(documentData,filename){const json=JSON.stringify(documentData,null,2),blob=new Blob([json],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;link.hidden=true;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);return {json,size:blob.size,filename}}
function downloadBackup({prefix='compasso-backup',updateTimestamp=true,withTime=false}={}){const exportedAt=new Date().toISOString(),documentData=createBackupDocument(exportedAt),filename=`${prefix}-${backupFileStamp(new Date(),withTime)}.json`,result=triggerJsonDownload(documentData,filename);if(updateTimestamp){data.settings=data.settings||{};data.settings.lastBackupAt=exportedAt;save()}return {...result,document:documentData}}
function validateBackupDocument(documentData){if(!documentData||typeof documentData!=='object'||Array.isArray(documentData))throw new Error('O arquivo não contém um backup válido.');if(documentData.format!==BACKUP_FORMAT)throw new Error('Este arquivo não foi criado pelo backup do Compasso.');if(documentData.backupVersion!==BACKUP_VERSION)throw new Error('Esta versão do arquivo de backup ainda não é compatível.');if(!documentData.data||typeof documentData.data!=='object'||Array.isArray(documentData.data))throw new Error('Os dados do backup estão ausentes.');for(const key of ['alunos','pagamentos','livros','repertorio'])if(!Array.isArray(documentData.data[key]))throw new Error(`A lista de ${key} está ausente ou danificada.`);if(documentData.data.classRecords!==undefined&&!Array.isArray(documentData.data.classRecords))throw new Error('O histórico de aulas está danificado.');if(documentData.data.settings!==undefined&&(!documentData.data.settings||typeof documentData.data.settings!=='object'||Array.isArray(documentData.data.settings)))throw new Error('As configurações do backup estão danificadas.');if(documentData.data.alunos.some(item=>!item||typeof item!=='object')||documentData.data.pagamentos.some(item=>!item||typeof item!=='object'))throw new Error('Há cadastros danificados no arquivo.');return documentData}
function backupSummary(backupData){const students=backupData.alunos||[];return {active:students.filter(student=>student.ativo!==false).length,former:students.filter(student=>student.ativo===false).length,classes:(backupData.classRecords||[]).length,payments:(backupData.pagamentos||[]).length,books:(backupData.livros||[]).length,repertoire:(backupData.repertorio||[]).length}}
function openBackupRestoreConfirmation(documentData,file){const importedData=photoFreeClone(documentData.data),summary=backupSummary(importedData),exported=formatBackupDate(documentData.exportedAt);modalShell('Restaurar backup',`<div class="backup-file"><i>↑</i><span><b>${esc(file.name)}</b><small>${esc(formatFileSize(file.size))} · exportado em ${esc(exported)}</small></span></div><div class="backup-summary"><span><b>${summary.active}</b><small>Alunos ativos</small></span><span><b>${summary.former}</b><small>Ex-alunos</small></span><span><b>${summary.classes}</b><small>Aulas salvas</small></span><span><b>${summary.payments}</b><small>Pagamentos</small></span><span><b>${summary.books}</b><small>Livros</small></span><span><b>${summary.repertoire}</b><small>Repertórios</small></span></div><div class="restore-warning"><b>Os dados atuais serão substituídos.</b><p>Antes disso, o Compasso baixará um backup de segurança. As fotos não fazem parte dos backups e serão removidas.</p></div>`);$('.modal .save').textContent='Restaurar dados';$('.modal').onsubmit=event=>{event.preventDefault();downloadBackup({prefix:'compasso-backup-antes-restauracao',updateTimestamp:false,withTime:true});const previousData=data;try{const restored=migrate(photoFreeClone(importedData));restored.classRecords=Array.isArray(restored.classRecords)?restored.classRecords:[];restored.settings={teacherName:'',schoolName:'',...(restored.settings||{}),lastImportAt:new Date().toISOString()};restored.demoEligible=false;restored.demoKurtSeyit=true;data=restored;migrateAcademicLinks();cleanOptionalBooks();if(!save()){data=previousData;showDuplicate('Não foi possível salvar o backup restaurado. Seus dados atuais foram mantidos.');delete $('.modal').dataset.committing;return}}catch(error){data=previousData;showDuplicate('Não foi possível restaurar este arquivo. Seus dados atuais foram mantidos.');delete $('.modal').dataset.committing;return}ui={...ui,page:'inicio',selectedStudent:null,selectedItem:null,selectedPayment:null,selectedClass:null,search:'',paymentMonth:0,moneyVisible:false,agendaView:'week',agendaMonth:0,showGoners:false};closeModal(true);toast('Backup restaurado com sucesso');render()}}
async function readBackupFile(file){if(!file)return;if(file.size>BACKUP_MAX_BYTES){showDuplicate('O arquivo ultrapassa o limite de 10 MB. Escolha um backup válido do Compasso.');return}try{const documentData=validateBackupDocument(JSON.parse(await file.text()));closeModal(true);openBackupRestoreConfirmation(documentData,file)}catch(error){showDuplicate(error instanceof SyntaxError?'O arquivo não é um JSON válido.':error.message||'Não foi possível ler este backup.')}}
function openProfileSettings(){let photoData=data.settings.foto||'';modalShell('Dados do professor',`${photoField('Foto do professor','f-photo',photoData)}${field('Seu nome','f-teacher','text',data.settings.teacherName||'','placeholder="Ex.: Alex Silva"')}${field('Nome da escola','f-school','text',data.settings.schoolName||'','placeholder="Ex.: Escola de Música Harmonia"')}<section class="backup-zone"><div class="backup-heading"><i>↕</i><span><b>Dados e backup</b><p>Salve uma cópia portátil dos cadastros, sem as fotos.</p></span></div><div class="backup-actions"><button type="button" class="backup-action" id="export-backup"><i>↓</i><span><b>Exportar</b><small>Criar arquivo</small></span></button><button type="button" class="backup-action" id="import-backup"><i>↑</i><span><b>Restaurar</b><small>Abrir backup</small></span></button></div><small class="backup-status" id="backup-status">${data.settings.lastBackupAt?`Último backup: ${esc(formatBackupDate(data.settings.lastBackupAt))}`:'Nenhum backup exportado'}</small><input id="backup-file" type="file" accept=".json,application/json" hidden></section><section class="erase-zone"><b>Apagar dados do aplicativo</b><p>Remove alunos, aulas, pagamentos, livros e repertório. Os dados do professor serão mantidos.</p><button type="button" class="danger-action" id="open-erase-data">Apagar todos os dados</button></section><small class="app-version">Compasso ${APP_VERSION}</small>`);bindPhotoEditor('f-photo',photoData,file=>photoData=file);const persistProfile=()=>{data.settings.teacherName=$('#f-teacher').value.trim();data.settings.schoolName=$('#f-school').value.trim();data.settings.foto=photoData;return save()};$('#export-backup').onclick=()=>{if(!persistProfile())return;const result=downloadBackup();$('.modal').dataset.dirty='false';$('#backup-status').textContent=`Último backup: ${formatBackupDate(result.document.exportedAt)}`;toast(`Backup exportado · ${formatFileSize(result.size)}`)};$('#import-backup').onclick=()=>{if($('.modal').dataset.dirty==='true'&&!confirm('Há alterações não salvas no perfil. Deseja descartá-las e escolher um backup?'))return;$('#backup-file').click()};$('#backup-file').onchange=event=>{const file=event.target.files?.[0];event.target.value='';readBackupFile(file)};$('#open-erase-data').onclick=()=>{if(closeModal())openEraseAllDataModal()};$('.modal').onsubmit=event=>{event.preventDefault();if(!persistProfile())return;closeModal();toast('Dados atualizados');render()}}

// Student contact, profile-managed books and reusable photo crops (v1.1.6)
function cropPercent(value){const number=Number(value);return Number.isFinite(number)?Math.max(0,Math.min(100,number)):50}
function photoStyle(photo){const value=typeof photo==='string'?{src:photo}:photo||{},zoom=Math.max(100,Math.min(280,Number(value.zoom)||100)),x=cropPercent(value.x),y=cropPercent(value.y),size=value.fit==='height'?`auto ${zoom}%`:`${zoom}% auto`;return `background-image:url('${value.src||''}');background-size:${size};background-position:${x}% ${y}%`}
function photoField(label,id,current=''){const src=photoSource(current);return `<div class="photo-editor"><span>${esc(label)}</span><div class="photo-editor-preview ${src?'has-photo':''}" id="${id}-preview" ${src?`style="${photoStyle(current)}"`:''}><i>♬</i><button type="button" class="photo-adjust-action" data-adjust-photo-for="${id}" aria-label="Reposicionar foto" title="Reposicionar foto" ${src?'':'hidden'}><span>✥</span></button><button type="button" class="camera-action" data-camera-for="${id}" aria-label="Abrir câmera" title="Trocar foto"><span></span></button><input class="camera-file-fallback" id="${id}" type="file" accept="image/*" capture="environment" tabindex="-1"></div><small>${src?'Use o ajuste para reposicionar ou a câmera para trocar.':'Toque na câmera para fotografar.'}</small></div>`}
function openCropper(photo,onSave){const current=typeof photo==='string'?{src:photo}:photo||{},src=current.src||'';let zoom=Math.max(100,Math.min(280,Number(current.zoom)||100)),x=cropPercent(current.x),y=cropPercent(current.y),fit=current.fit==='height'?'height':current.fit==='width'?'width':'',start=null;document.body.insertAdjacentHTML('beforeend',`<div class="modal-back crop-back"><section class="modal crop-modal"><small>FOTO</small><h2>Ajustar miniatura</h2><p>Arraste para posicionar e use o controle para aproximar.</p><div class="crop-frame"><img class="crop-loader" src="${esc(src)}" alt=""></div><label>Aproximação<input class="crop-zoom" type="range" min="100" max="280" value="${zoom}"></label><div class="crop-actions"><button type="button" class="close-crop">Cancelar</button><button type="button" class="save crop-save">Usar foto</button></div></section></div>`);const back=$('.crop-back'),frame=$('.crop-frame',back),loader=$('.crop-loader',frame),slider=$('.crop-zoom',back),paint=()=>{if(fit)frame.setAttribute('style',photoStyle({src,zoom,x,y,fit}))};slider.oninput=()=>{zoom=Number(slider.value);paint()};frame.onpointerdown=event=>{start={px:event.clientX,py:event.clientY,x,y};frame.setPointerCapture?.(event.pointerId)};frame.onpointermove=event=>{if(!start)return;const width=frame.clientWidth||280,height=frame.clientHeight||280;x=Math.max(0,Math.min(100,start.x+(event.clientX-start.px)/width*100));y=Math.max(0,Math.min(100,start.y+(event.clientY-start.py)/height*100));paint()};frame.onpointerup=frame.onpointercancel=()=>start=null;$('.close-crop',back).onclick=()=>back.remove();$('.crop-save',back).onclick=()=>{onSave({src,zoom,x,y,fit:fit||'width'});back.remove();toast('Miniatura ajustada')};loader.onload=()=>{if(!fit)fit=loader.naturalWidth>=loader.naturalHeight?'height':'width';paint()};if(loader.complete)loader.onload()}
function bindPhotoEditor(id,current,onChange){const input=$(`#${id}`),preview=$(`#${id}-preview`),camera=$(`[data-camera-for="${id}"]`),adjust=$(`[data-adjust-photo-for="${id}"]`);if(!input)return;let selected=current;const apply=photo=>{selected=photo;if(preview){preview.classList.add('has-photo');preview.setAttribute('style',photoStyle(photo));preview.closest('.modal')?.setAttribute('data-dirty','true')}if(adjust)adjust.hidden=false;onChange(photo)};input.onchange=()=>readPhoto(input,apply);if(camera)camera.onclick=()=>openDirectCamera(input,apply);if(adjust)adjust.onclick=()=>{const src=photoSource(selected);if(src)openCropper(selected,apply)}}
function whatsappDigits(contact){const raw=String(contact||'').trim(),explicitCountry=raw.startsWith('+');let digits=raw.replace(/\D/g,'');if(digits.startsWith('0'))digits=digits.slice(1);if(!explicitCountry&&(digits.length===10||digits.length===11))digits=`55${digits}`;return digits.length>=8?digits:''}
function whatsappContact(student){const digits=whatsappDigits(student.contato);if(!digits)return '';return `<a class="whatsapp-contact" href="https://wa.me/${digits}" target="_blank" rel="noopener noreferrer" aria-label="Conversar com ${esc(student.nome)} no WhatsApp"><i>☎</i><span><small>WhatsApp</small><b>${esc(student.contato)}</b></span><strong>›</strong></a>`}
