save=function(){try{const canonical=schemaV2Engine.canonicalOnly(data);localStorage.setItem(STORAGE_KEY,JSON.stringify(canonical));if(canonical.meta?.dataErased)localStorage.removeItem(SCHEMA_V1_RECOVERY_KEY);return true}catch(error){toast('Armazenamento cheio. Remova algumas fotos ou dados antes de continuar.');return false}};

