function paymentByIdV2(id){const key=String(id);return paymentProjectionCacheV2.get(key)||data.pagamentos.find(payment=>String(payment.id)===key||String(payment.autoKey)===key)||projectedPaymentsV2().find(payment=>String(payment.id)===key)}
function persistPaymentSparse(payment){const key=String(payment.autoKey||payment.id),existing=data.pagamentos.find(item=>String(item.autoKey||item.id)===key);if(existing)return existing;const stored={...payment,id:key,autoKey:key,_persisted:true,_virtual:false,history:[...(payment.history||[])]};data.pagamentos.push(stored);return stored}
