weeklyAgenda=function(){const monday=weekStart(),sunday=new Date(monday);sunday.setDate(monday.getDate()+6);const from=localISO(monday),to=localISO(sunday),today=todayISO(),records=projectedClassesV2(from,to);const dayContent=day=>{const date=weekDateForDay(monday,day),dateKey=localISO(date),entries=records.filter(record=>record.day===day).sort((a,b)=>a.time.localeCompare(b.time)),ghosts=data.alunos.filter(student=>student.ativo!==false&&(!student.desde||dateKey>=student.desde)).flatMap(student=>classSlots(student).filter(slot=>slot.dia===day).filter(slot=>{const slotStart=slot.criadoEm||student.desde;return dateKey<today&&slotStart&&dateKey<slotStart&&slotStart<=to}).map(slot=>({student,slot}))).filter(({student,slot})=>!entries.some(record=>String(record.studentId)===String(student.id)&&record.time===slot.hora)),birthdays=birthdayStudentsOn(date).filter(student=>!entries.some(record=>String(record.studentId)===String(student.id))&&!ghosts.some(ghost=>String(ghost.student.id)===String(student.id)));return {date,entries,ghosts,birthdays}};const contents=DAYS.map(day=>({day,...dayContent(day)})),days=contents.filter((content,index)=>index<5||content.entries.length||content.ghosts.length||content.birthdays.length);return header('ROTINA E HISTÓRICO','Agenda','<button class="add" data-modal="aluno" aria-label="Novo aluno">＋</button>')+agendaSwitch()+`<div class="status-legend"><i class="held"></i>Realizada<i class="cancelled"></i>Cancelada<i class="missed"></i>Falta<i class="rescheduled"></i>Reagendada<i class="birthday"></i>Aniversário</div><div class="week-agenda">${days.map(({day,entries,ghosts,birthdays})=>{const count=entries.length;return `<section class="week-day"><div><b>${day}</b><small>${count} ${count===1?'aula':'aulas'}</small></div>${entries.map(classAgendaEntry).join('')}${ghosts.map(({student,slot})=>ghostClassEntry(student,slot,weekDateForDay(monday,day))).join('')}${birthdays.map(birthdayOnlyEntry).join('')}${!entries.length&&!ghosts.length&&!birthdays.length?'<p>—</p>':''}</section>`}).join('')}</div>`};
monthlyAgenda=function(){const month=monthLabel(ui.agendaMonth),last=localISO(new Date(month.date.getFullYear(),month.date.getMonth()+1,0)),records=projectedClassesV2(`${month.key}-01`,last),birthdayDates=data.alunos.flatMap(student=>{const date=birthdayDate(student,month.date.getFullYear());if(!date)return[];const key=localISO(date);return key.startsWith(month.key)&&studentActiveOn(student,key)?[key]:[]}),groups=[...new Set([...records.map(record=>record.date),...birthdayDates])].sort();let previousWeek='';return header('HISTÓRICO DE AULAS','Agenda')+agendaSwitch()+`<div class="month"><button data-agenda-month="-1">‹</button><b>${esc(month.label)}</b><button data-agenda-month="1">›</button></div><div class="status-legend"><i class="held"></i>Realizada<i class="cancelled"></i>Cancelada<i class="missed"></i>Falta<i class="rescheduled"></i>Reagendada<i class="birthday"></i>Aniversário</div><div class="month-history">${groups.length?groups.map(date=>{const currentWeek=weekGroup(date),breakClass=previousWeek&&currentWeek!==previousWeek?'week-break':'';previousWeek=currentWeek;const dayRecords=records.filter(record=>record.date===date),dayDate=new Date(`${date}T12:00:00`),birthdays=birthdayStudentsOn(dayDate).filter(student=>!dayRecords.some(record=>String(record.studentId)===String(student.id)));return `<section class="${breakClass}"><div class="history-date"><b>${esc(dayDate.toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}))}</b><small>${esc(DAYS[(dayDate.getDay()+6)%7])}</small></div><div>${dayRecords.map(classAgendaEntry).join('')}${birthdays.map(birthdayOnlyEntry).join('')}</div></section>`}).join(''):'<p class="empty">Nenhuma aula ou aniversário neste mês.</p>'}</div>`};
classDetail=function(){const record=classByIdV2(ui.selectedClass),student=data.alunos.find(item=>String(item.id)===String(record?.studentId));if(!record||!student){ui.selectedClass=null;return schedule()}const labels={pending:'Não registrada',held:'Aula realizada',teacher_cancel:'Cancelada pelo professor',student_cancel:'Cancelada pelo aluno',no_show:'Aluno não compareceu'};return header('AULA',student.nome,'<button class="close" data-close-class>×</button>')+`<div class="profile">${avatar(student)}<span><small>${record.rescheduled?'● AULA REAGENDADA':'AULA DA SEMANA'}</small><h2>${esc(record.day)}, ${esc(record.time)}</h2><p>${record.duration||50} minutos · ${formatDateBR(record.date)}</p></span></div><section class="panel"><h3>Situação da aula</h3><div class="class-statuses">${[['held','✓','Aconteceu'],['teacher_cancel','×','Professor cancelou'],['student_cancel','×','Aluno cancelou'],['no_show','!','Não compareceu']].map(option=>`<button class="${record.status===option[0]?'active':''}" data-class-status="${option[0]}"><i>${option[1]}</i><span>${option[2]}</span></button>`).join('')}</div><p class="status-note">Atual: <b>${labels[record.status]||labels.pending}</b></p>${['teacher_cancel','student_cancel'].includes(record.status)?`<button class="save" data-reschedule>${record.rescheduledTo?'Alterar reagendamento':'Reagendar aula'}</button>`:''}</section><section class="panel"><h3>Comentário da aula</h3><textarea data-class-note placeholder="Conteúdo trabalhado, exercícios, comportamento ou lembretes...">${esc(record.notes||'')}</textarea></section><button class="person-line" data-student="${student.id}">${avatar(student)}<span><b>Abrir cadastro do aluno</b><small>Livro, repertório e observações</small></span>›</button>`};
