stopStudent=function(studentId){const student=data.alunos.find(item=>String(item.id)===String(studentId));if(!student)return;if(student.ativo===false){student.ativo=true;delete student.encerradoEm;data.pagamentos=(data.pagamentos||[]).filter(payment=>!(payment._excluded&&payment.exclusionReason==='student_ended'&&String(payment.alunoId)===String(student.id)));save();toast('Aluno reativado');render();return}const currentMonthPayments=projectedPaymentsV2(0).filter(payment=>String(payment.alunoId)===String(student.id)),end=todayISO();student.ativo=false;student.encerradoEm=end;data.classRecords=(data.classRecords||[]).filter(record=>String(record.studentId)!==String(student.id)||record.date<=end);data.pagamentos=(data.pagamentos||[]).filter(payment=>String(payment.alunoId)!==String(student.id)||!payment.dueDate||payment.dueDate<=end);if(confirm('Excluir também todos os pagamentos deste aluno no mês atual? Isso pode incluir pagamentos já confirmados.'))currentMonthPayments.forEach(projected=>{const payment=persistPaymentSparse(projected);payment.pago=false;delete payment.pagoEm;payment._excluded=true;payment.exclusionReason='student_ended';paymentEventSparse(payment,'excluded_when_student_ended')});save();toast('Aulas encerradas; ocorrências futuras deixarão de ser exibidas');render()};

