function withActiveAcademicLinksFirst(callback){const originalRelationLastDate=relationLastDate;relationLastDate=relation=>`${relation?.fim?'0':'1'}:${originalRelationLastDate(relation)}`;try{return callback()}finally{relationLastDate=originalRelationLastDate}}

